from pathlib import Path
root=Path(__file__).resolve().parents[1]/'web'
def edit(name,old,new):
    p=root/name
    s=p.read_text(encoding='utf-8')
    assert old in s,name
    p.write_text(s.replace(old,new,1),encoding='utf-8')

